function accept_fix(fix_case, ask) {
  const jobs = fix_case.jobs || [];
  const nearby = fix_case.nearby || [];

  const repaired = jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const repairedJobs = jobs.filter(j => j.before === 'fail' && j.after === 'pass');
  const passingJobs = jobs.filter(j => j.before === 'pass');
  const jobNames = new Set(jobs.map(j => j.name));

  const tokenize = s => (s || '').toLowerCase().match(/[a-z0-9]+/g) || [];

  const overlap = (tokensA, tokensB) => {
    const setB = new Set(tokensB);
    let inter = 0;
    for (const t of tokensA) if (setB.has(t)) inter++;
    return tokensB.length ? inter / tokensB.length : 0;
  };

  const quotedName = s => {
    const m = s.match(/"([^"]+)"|'([^']+)'/);
    return m ? (m[1] || m[2]) : null;
  };

  const candidates = [];

  for (const n of nearby) {
    if (n.before === n.after) continue;

    const situation = n.situation || '';
    const quoted = quotedName(situation);

    // Skip exact job situations; the jobs list already covers those.
    if (quoted && jobNames.has(quoted) && !situation.includes(', but')) continue;

    const candTokens = tokenize(situation);
    let maxRep = 0;
    for (const j of repairedJobs) {
      const sim = overlap(candTokens, tokenize(j.name));
      if (sim > maxRep) maxRep = sim;
    }

    let maxPass = 0;
    for (const j of passingJobs) {
      const sim = overlap(candTokens, tokenize(j.name));
      if (sim > maxPass) maxPass = sim;
    }

    let score = Math.min(maxRep, maxPass) * 2 + maxRep + maxPass;
    if (/\b(not|no|without|never|does not|doesn't)\b/i.test(situation)) {
      score += 0.5;
    }

    candidates.push({ id: n.id, before: n.before, after: n.after, score });
  }

  candidates.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return a.id - b.id;
  });

  let asked = 0;
  for (const cand of candidates) {
    if (asked >= 3) break;
    const truth = ask(cand.id);
    asked++;
    if (truth === null) break;
    if (truth === cand.before) return false;
  }

  return true;
}

function accept_fix(fix_case, ask) {
  const jobs = fix_case.jobs || [];
  const nearby = fix_case.nearby || [];

  // Must repair at least one job and not lose any
  const repaired = jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const jobNames = new Set(jobs.map(j => j.name));

  const tokenize = s => (s || '').toLowerCase().match(/[a-z0-9]+/g) || [];
  const jaccard = (a, b) => {
    const setA = new Set(a);
    const setB = new Set(b);
    let inter = 0;
    for (const x of setA) if (setB.has(x)) inter++;
    const union = setA.size + setB.size - inter;
    return union === 0 ? 0 : inter / union;
  };

  const extractBase = (situation) => {
    let m = situation.match(/job\s+"([^"]+)"/i);
    if (m) return m[1];
    m = situation.match(/job\s+'([^']+)'/i);
    if (m) return m[1];
    m = situation.match(/the situation of job\s+([^,]+)/i);
    if (m) return m[1].trim();
    return situation;
  };

  const hasNegation = (s) => /\b(not|no|without|never|does not|doesn't|isn't|aren't|wasn't|weren't|hasn't|haven't|hadn't|can't|cannot|won't|wouldn't|shouldn't|couldn't|mustn't)\b/i.test(s || '');

  const candidates = [];

  for (const n of nearby) {
    if (n.before === n.after) continue;
    const situation = n.situation || '';
    const base = extractBase(situation);
    const baseTokens = tokenize(base);

    // Skip exact job situations (no "but" and base matches a job name)
    const hasBut = /,\s*but\b/i.test(situation);
    if (!hasBut && jobNames.has(base)) continue;

    const neg = hasNegation(situation);
    let bestScore = 0;

    for (const j of jobs) {
      const jTokens = tokenize(j.name);
      const sim = jaccard(baseTokens, jTokens);
      if (sim < 0.3) continue;

      let bonus = 0;
      if (j.before === 'pass') bonus += 2.0;
      if (j.before === 'fail' && j.after === 'pass' && neg) bonus += 2.0;

      const score = sim + bonus;
      if (score > bestScore) bestScore = score;
    }

    if (bestScore === 0 && neg) bestScore = 1.0;

    candidates.push({ id: n.id, before: n.before, score: bestScore });
  }

  candidates.sort((a, b) => b.score - a.score || a.id - b.id);

  let asked = 0;
  for (const cand of candidates) {
    if (asked >= 3) break;
    const truth = ask(cand.id);
    asked++;
    if (truth === null) break;
    if (truth === cand.before) return false;
  }

  return true;
}

